<?php
 namespace Pterodactyl\Jobs\Dezerx; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Cache; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Pterodactyl\Services\Dezerx\Minecraft\Worlds; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Services\Dezerx\Minecraft\ServerProperties; class InstallWorld extends Job implements ShouldQueue { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 1800; public int $tries = 1; private const STAGING = '.world-install'; private const MAX_DEPTH = 2; public function __construct( public Server $server, public string $url, public string $filename, public string $name, public bool $activate, ) { $this->queue = 'standard'; } public static function statusKey(string $server): string { return "dezerx:world-install:{$server}"; } public static function status(string $server): array { return Cache::get(self::statusKey($server)) ?? ['state' => 'idle']; } public static function queued(string $server, string $file): void { Cache::put(self::statusKey($server), [ 'state' => 'downloading', 'message' => "Fetching {$file}.", 'file' => $file, ], 1800); } public function handle(): void { $files = new ServerFiles($this->server); $this->report('downloading', "Fetching {$this->filename}."); $files->deletePaths('/', [self::STAGING]); if (!$files->createDirectory('/'.self::STAGING)) { $this->fail('The node would not make a folder to unpack into.'); return; } if (!$files->pullFile('/'.self::STAGING, $this->url, $this->filename)) { $this->fail('The node would not accept that download.'); return; } if (!$this->awaitFile($files)) { $this->fail('The download never finished. The map may be very large, or CurseForge may be refusing the node.'); return; } $this->report('unpacking', 'Unpacking the map.'); if (!$files->decompress('/'.self::STAGING, $this->filename)) { $this->fail('That archive could not be unpacked.'); return; } $files->deletePaths('/'.self::STAGING, [$this->filename]); $source = $this->findWorld($files, '/'.self::STAGING, 0); if ($source === null) { $files->deletePaths('/', [self::STAGING]); $this->fail('There is no level.dat anywhere in that download, so it is not a Java world. It may be a Bedrock map or a resource pack.'); return; } $this->report('placing', 'Putting the world in place.'); $name = $this->freeName($files); if (!$this->move($files, $source, $name)) { $files->deletePaths('/', [self::STAGING]); $this->fail('The world could not be moved into place.'); return; } $files->deletePaths('/', [self::STAGING]); $activated = $this->activate($files, $name); Worlds::forget($this->server->uuid); Cache::forget("dezerx:playerlevel:{$this->server->uuid}"); $this->report('done', $activated ? "{$name} is installed and is now the world the server runs. Start it up." : "{$name} is installed. Switch to it from its card when the server is stopped.", $name); } private function findWorld(ServerFiles $files, string $path, int $depth): ?string { $entries = $files->listFiles($path); if ($entries === null) { return null; } foreach ($entries as $entry) { if (($entry['name'] ?? '') === 'level.dat') { return $path; } } if ($depth >= self::MAX_DEPTH) { return null; } foreach ($entries as $entry) { if (!($entry['directory'] ?? false)) { continue; } $found = $this->findWorld($files, $path.'/'.$entry['name'], $depth + 1); if ($found !== null) { return $found; } } return null; } private function move(ServerFiles $files, string $source, string $name): bool { $from = ltrim($source, '/'); return $files->renamePath('/', $from, $name); } private function freeName(ServerFiles $files): string { $taken = array_map( fn (array $entry) => mb_strtolower((string) ($entry['name'] ?? '')), $files->listFiles('/') ?? [], ); if (!in_array(mb_strtolower($this->name), $taken, true)) { return $this->name; } for ($suffix = 2; $suffix < 100; $suffix++) { $candidate = "{$this->name}-{$suffix}"; if (!in_array(mb_strtolower($candidate), $taken, true)) { return $candidate; } } return $this->name.'-'.time(); } private function activate(ServerFiles $files, string $name): bool { if (!$this->activate || $files->powerState() !== 'offline') { return false; } return ServerProperties::write($files, ['level-name' => $name]); } private function awaitFile(ServerFiles $files, int $minutes = 20): bool { $deadline = microtime(true) + ($minutes * 60); $previous = null; do { sleep(5); $size = $files->entrySize('/'.self::STAGING, $this->filename); if ($size !== null && $size > 0 && $size === $previous) { return true; } $previous = $size; } while (microtime(true) < $deadline); return false; } private function report(string $state, string $message, ?string $world = null): void { Cache::put(self::statusKey($this->server->uuid), array_filter([ 'state' => $state, 'message' => $message, 'world' => $world, 'file' => $this->filename, ]), 1800); } private function fail(string $message): void { Log::warning('World install failed', [ 'server' => $this->server->uuid, 'file' => $this->filename, 'reason' => $message, ]); $this->report('failed', $message); } public function failed(\Throwable $exception): void { $this->fail('The install stopped unexpectedly. Check the panel log.'); } } 